#!/usr/bin/env bash
# bin/bootstrap-local.sh
# Run inside WSL on the target machine
# This script sets up SSH server in WSL for remote Ansible access
# Note: host_vars are generated by bootstrap-local.ps1 on the Windows side

set -euo pipefail

# Ensure passwordless sudo for the current user (needed for Ansible become)
WSL_USER="${SUDO_USER:-${USER}}"

if [[ -z "${WSL_USER}" || "${WSL_USER}" == "root" ]]; then
  echo "ERROR: cannot determine non-root WSL user for sudoers" >&2
  exit 1
fi

echo "Configuring passwordless sudo for user: ${WSL_USER}"
sudo bash -lc "echo '${WSL_USER} ALL=(ALL) NOPASSWD:ALL' > /etc/sudoers.d/${WSL_USER} && chmod 440 /etc/sudoers.d/${WSL_USER}"

# Run inside WSL on the target machine
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

cd "$REPO_ROOT"

echo "Setting up SSH server in WSL..."

# Install openssh-server if not present
if ! command -v sshd >/dev/null 2>&1; then
  sudo apt-get update
  sudo apt-get install -y openssh-server
fi

# Ensure sshd runtime directory exists
sudo mkdir -p /var/run/sshd

# Enable SSH service (WSL may use systemd or init.d)
if systemctl is-system-running >/dev/null 2>&1; then
  sudo systemctl enable ssh 2>/dev/null || true
  sudo systemctl start ssh 2>/dev/null || sudo service ssh start 2>/dev/null || true
else
  sudo service ssh start 2>/dev/null || true
fi

# Ensure pubkey authentication is enabled in sshd_config
if ! grep -q "^PubkeyAuthentication yes" /etc/ssh/sshd_config 2>/dev/null; then
  # Comment out any existing PubkeyAuthentication line and add our setting
  sudo sed -i 's/^#*PubkeyAuthentication.*/PubkeyAuthentication yes/' /etc/ssh/sshd_config
  # If no line exists, add it
  if ! grep -q "^PubkeyAuthentication" /etc/ssh/sshd_config 2>/dev/null; then
    echo "PubkeyAuthentication yes" | sudo tee -a /etc/ssh/sshd_config >/dev/null
  fi
  
  # Restart SSH to apply changes
  if systemctl is-system-running >/dev/null 2>&1; then
    sudo systemctl restart ssh 2>/dev/null || sudo service ssh restart 2>/dev/null || true
  else
    sudo service ssh restart 2>/dev/null || true
  fi
fi

echo "WSL SSH setup complete. SSH server is running and configured for pubkey authentication."
echo "Note: host_vars files should already be generated by bootstrap-local.ps1 on Windows side."
